import { useCallback, useMemo } from 'react';

import {
  getIntentLink,
  type IntentPayload,
  sendIntent,
} from '@dynatrace-sdk/navigation';

/**
 * return shared intent button logic
 * @param payload - an intent payload
 * @returns intentLink and triggerIntent
 */
export function useIntentButton(
  payload: IntentPayload,
  appId?: string,
  intentId?: string,
  onClickProp?: React.MouseEventHandler,
) {
  /**
   * Contains the url created via the getIntentLink SDK method.
   * @returns a url to be used
   */
  const href = useMemo(
    () =>
      // SDK documentation is invalid. appId & intentId are in fact mandatory.
      // This is why the ternary is necessary to ensure to call the correct signature.
      appId && intentId
        ? getIntentLink(payload, appId, intentId)
        : getIntentLink(payload),
    [appId, intentId, payload],
  );

  /**
   * Sends intent to shell.
   * @returns void
   */
  const triggerIntent = useCallback(() => {
    // SDK documentation is invalid. appId & intentId are in fact mandatory.
    // This is why the ternary is necessary to ensure to call the correct signature.
    appId && intentId
      ? sendIntent(payload, appId, intentId)
      : sendIntent(payload);
  }, [appId, intentId, payload]);

  /**
   * Mouse event handler, send intent on left button click without using any modifiers.
   */
  const onClick = useCallback(
    (event: React.MouseEvent) => {
      onClickProp?.(event);
      if (event.isDefaultPrevented()) {
        // already handled
        return;
      }

      const nativeEvent = event.nativeEvent;

      if (
        nativeEvent.button !== 0 ||
        nativeEvent.metaKey ||
        nativeEvent.ctrlKey ||
        nativeEvent.shiftKey
      ) {
        return; // let the browser handle the event
      }

      event.preventDefault();
      triggerIntent();
    },
    [onClickProp, triggerIntent],
  );

  /**
   * KeyDown event handler, sent intent on Space and ENTER
   */
  const onKeyDown = useCallback(
    (event: React.KeyboardEvent) => {
      const nativeEvent = event.nativeEvent;

      if (nativeEvent.code !== 'Space' && nativeEvent.code !== 'Enter') {
        return; // let the browser handle the event
      }

      event.preventDefault();

      // open intent link in new tab while pressing ctrl/meta
      if (nativeEvent.metaKey || nativeEvent.ctrlKey) {
        window.open(href);
        return;
      }

      // open intent link in new window
      if (nativeEvent.shiftKey) {
        window.open(href, '_blank', 'menubar');
        return;
      }

      // let the shell handle the intent
      triggerIntent();
    },
    [href, triggerIntent],
  );

  return { href, onClick, onKeyDown };
}
